mapper.select:
select ccma.RECORD_ID, ppa.PROJECT_ATTACHMENT_ID FILE_NAME_ID, ppa.project_attachment_category FILE_CATEGORY, decode(ppa.project_attachment_category,'PRJ_LEASE','尽调资料（租赁物）', 'PRJ_BP_CZ','尽调资料（承租人）','PRJ_BP_DB','尽调资料（担保人）') FILE_CATEGORY_N, ppa.DOCUMENT_NAME FILE_NAME, (select listagg(faa.file_name, '、') within group(order by faa.attachment_id) from fnd_atm_attachment faa , fnd_atm_attachment_multi faam where faam.ATTACHMENT_ID = faa.ATTACHMENT_ID and faam.RECORD_ID = faa.SOURCE_PK_VALUE and faam.TABLE_PK_VALUE = ppa.PROJECT_ATTACHMENT_ID and faam.table_name = 'PRJ_PROJECT_ATTACHMENT') ATTACHMENT_NAME, (select COUNT(faam.RECORD_ID) from fnd_atm_attachment_multi faam,fnd_atm_attachment faa where faam.ATTACHMENT_ID = faa.ATTACHMENT_ID and faam.RECORD_ID = faa.SOURCE_PK_VALUE and faam.TABLE_PK_VALUE = ppa.PROJECT_ATTACHMENT_ID and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' ) COPIES, (select faa.CREATION_DATE from fnd_atm_attachment faa where faa.ATTACHMENT_ID =(select max(faa.ATTACHMENT_ID) from fnd_atm_attachment_multi faam,fnd_atm_attachment faa where faam.ATTACHMENT_ID = faa.ATTACHMENT_ID and faam.RECORD_ID = faa.SOURCE_PK_VALUE and faam.TABLE_PK_VALUE = ppa.PROJECT_ATTACHMENT_ID and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' )) UPLOAD_DATE, ccma.REMARKS, (select cca.contract_id from con_contract_archive cca where cca.contract_archive_id = ccma.contract_archive_id) CONTRACT_ID, ccma.CONTRACT_ARCHIVE_ID from prj_project_attachment ppa left join con_contract_archive_multi ccma on ppa.PROJECT_ATTACHMENT_ID = ccma.FILE_NAME_ID
ppa.project_attachment_category IN ( 'PRJ_BP_CZ', 'PRJ_BP_DB', 'PRJ_LEASE' ) and ppa.project_id = #{id}
AND ppa.project_attachment_category = #{archiveType}
